//! Scroll gesture phases that are safe to feed into CoreGraphics.
//!
//! The App sends gesture and momentum phases from RSP/1 §6.1. A lost event or
//! reconnect can leave those phases unbalanced, which makes macOS applications
//! stay in a scrolling state. This module wraps [`ScrollAccumulator`] with a
//! small state machine that always emits `Began -> Changed* -> Ended`, followed
//! optionally by momentum `Begin -> Continue* -> End`.
//!
//! Inertia is generated by the App and arrives as `momentum`; the Host never
//! invents momentum deltas. The current wire protocol also has no MayBegin or
//! Cancelled phase, so this module emits neither CoreGraphics value.

use rsp_core::hid::{InputMsg, ScrollPhase};

use super::scroll::{MacScroll, ScrollAccumulator};

/// End a gesture that has received no event for this many microseconds.
pub const GESTURE_IDLE_END_US: u64 = 300_000;

/// End inertia that has received no event for this many microseconds.
pub const MOMENTUM_IDLE_END_US: u64 = 300_000;

const CG_SCROLL_PHASE_BEGAN: u32 = 1;
const CG_SCROLL_PHASE_ENDED: u32 = 4;
const CG_MOMENTUM_PHASE_BEGIN: u32 = 1;
const CG_MOMENTUM_PHASE_END: u32 = 3;

/// Current phase family of a scroll gesture.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GestureState {
    Idle,
    Scrolling,
    Momentum,
}

/// One CoreGraphics-ready scroll event.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MacScrollEvent {
    pub scroll: MacScroll,
    /// Value for `kCGScrollWheelEventIsContinuous`.
    pub continuous: bool,
    /// True when this event closes or opens a phase on the App's behalf.
    pub synthetic: bool,
}

/// Counters accumulated over the lifetime of a [`ScrollGesture`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct ScrollStats {
    pub dropped: u64,
    pub synthesized: u64,
}

/// Normalize a stream of RSP scroll events into legal CoreGraphics phases.
#[derive(Debug)]
pub struct ScrollGesture {
    state: GestureState,
    accumulator: ScrollAccumulator,
    last_us: u64,
    stats: ScrollStats,
}

impl ScrollGesture {
    /// Create an idle gesture state machine.
    pub fn new(pixels_per_line: f64) -> Self {
        Self {
            state: GestureState::Idle,
            accumulator: ScrollAccumulator::with_pixels_per_line(pixels_per_line),
            last_us: 0,
            stats: ScrollStats::default(),
        }
    }

    /// Process one input message at the supplied Unix time in microseconds.
    pub fn on_scroll(&mut self, msg: &InputMsg, now_us: u64) -> Vec<MacScrollEvent> {
        let Some(input) = classify_scroll(msg) else {
            self.stats.dropped += 1;
            return Vec::new();
        };

        let mut output = Vec::with_capacity(3);
        let (next_state, accepted) = match (self.state, input) {
            (GestureState::Idle, ScrollInput::Wheel) => {
                self.push_real(&mut output, msg, false);
                (GestureState::Idle, true)
            }
            (GestureState::Idle, ScrollInput::Gesture(GestureInput::Began)) => {
                self.push_real(&mut output, msg, true);
                (GestureState::Scrolling, true)
            }
            (GestureState::Idle, ScrollInput::Gesture(GestureInput::Changed)) => {
                self.push_synthetic(&mut output, Synthetic::GestureBegan);
                self.push_real(&mut output, msg, true);
                (GestureState::Scrolling, true)
            }
            (GestureState::Idle, ScrollInput::Gesture(GestureInput::Ended)) => {
                self.stats.dropped += 1;
                (GestureState::Idle, false)
            }
            (GestureState::Idle, ScrollInput::Momentum(MomentumInput::Began)) => {
                self.push_real(&mut output, msg, true);
                (GestureState::Momentum, true)
            }
            (GestureState::Idle, ScrollInput::Momentum(MomentumInput::Changed)) => {
                self.push_synthetic(&mut output, Synthetic::MomentumBegin);
                self.push_real(&mut output, msg, true);
                (GestureState::Momentum, true)
            }
            (GestureState::Idle, ScrollInput::Momentum(MomentumInput::Ended)) => {
                self.stats.dropped += 1;
                (GestureState::Idle, false)
            }

            (GestureState::Scrolling, ScrollInput::Gesture(GestureInput::Changed)) => {
                self.push_real(&mut output, msg, true);
                (GestureState::Scrolling, true)
            }
            (GestureState::Scrolling, ScrollInput::Gesture(GestureInput::Ended)) => {
                self.push_real(&mut output, msg, true);
                (GestureState::Idle, true)
            }
            (GestureState::Scrolling, ScrollInput::Gesture(GestureInput::Began)) => {
                self.push_synthetic(&mut output, Synthetic::GestureEnded);
                self.push_real(&mut output, msg, true);
                (GestureState::Scrolling, true)
            }
            (GestureState::Scrolling, ScrollInput::Wheel) => {
                self.push_synthetic(&mut output, Synthetic::GestureEnded);
                self.push_real(&mut output, msg, false);
                (GestureState::Idle, true)
            }
            (GestureState::Scrolling, ScrollInput::Momentum(MomentumInput::Began)) => {
                self.push_synthetic(&mut output, Synthetic::GestureEnded);
                self.push_real(&mut output, msg, true);
                (GestureState::Momentum, true)
            }
            (GestureState::Scrolling, ScrollInput::Momentum(MomentumInput::Changed)) => {
                self.push_synthetic(&mut output, Synthetic::GestureEnded);
                self.push_synthetic(&mut output, Synthetic::MomentumBegin);
                self.push_real(&mut output, msg, true);
                (GestureState::Momentum, true)
            }
            (GestureState::Scrolling, ScrollInput::Momentum(MomentumInput::Ended)) => {
                self.push_synthetic(&mut output, Synthetic::GestureEnded);
                self.stats.dropped += 1;
                (GestureState::Idle, false)
            }

            (GestureState::Momentum, ScrollInput::Momentum(MomentumInput::Changed)) => {
                self.push_real(&mut output, msg, true);
                (GestureState::Momentum, true)
            }
            (GestureState::Momentum, ScrollInput::Momentum(MomentumInput::Ended)) => {
                self.push_real(&mut output, msg, true);
                (GestureState::Idle, true)
            }
            (GestureState::Momentum, ScrollInput::Momentum(MomentumInput::Began)) => {
                self.push_synthetic(&mut output, Synthetic::MomentumEnd);
                self.push_real(&mut output, msg, true);
                (GestureState::Momentum, true)
            }
            (GestureState::Momentum, ScrollInput::Gesture(GestureInput::Began)) => {
                self.push_synthetic(&mut output, Synthetic::MomentumEnd);
                self.push_real(&mut output, msg, true);
                (GestureState::Scrolling, true)
            }
            (GestureState::Momentum, ScrollInput::Gesture(GestureInput::Changed)) => {
                self.push_synthetic(&mut output, Synthetic::MomentumEnd);
                self.push_synthetic(&mut output, Synthetic::GestureBegan);
                self.push_real(&mut output, msg, true);
                (GestureState::Scrolling, true)
            }
            (GestureState::Momentum, ScrollInput::Gesture(GestureInput::Ended)) => {
                self.push_synthetic(&mut output, Synthetic::MomentumEnd);
                self.stats.dropped += 1;
                (GestureState::Idle, false)
            }
            (GestureState::Momentum, ScrollInput::Wheel) => {
                self.push_synthetic(&mut output, Synthetic::MomentumEnd);
                self.push_real(&mut output, msg, false);
                (GestureState::Idle, true)
            }
        };

        if accepted {
            self.last_us = now_us;
        }
        self.state = next_state;
        output
    }

    /// Close a phase whose idle timeout has elapsed.
    ///
    /// The caller should invoke this periodically and whenever a timer set from
    /// [`Self::next_deadline`] fires.
    pub fn poll(&mut self, now_us: u64) -> Vec<MacScrollEvent> {
        let timeout = match self.state {
            GestureState::Idle => return Vec::new(),
            GestureState::Scrolling => GESTURE_IDLE_END_US,
            GestureState::Momentum => MOMENTUM_IDLE_END_US,
        };
        if now_us.saturating_sub(self.last_us) < timeout {
            return Vec::new();
        }

        let mut output = Vec::with_capacity(1);
        match self.state {
            GestureState::Idle => return output,
            GestureState::Scrolling => {
                self.push_synthetic(&mut output, Synthetic::GestureEnded);
                self.state = GestureState::Idle;
            }
            GestureState::Momentum => {
                self.push_synthetic(&mut output, Synthetic::MomentumEnd);
                self.state = GestureState::Idle;
            }
        }
        output
    }

    /// Close any active phase and discard fractional pixels.
    ///
    /// Use this for ReleaseAll, controller changes, and session teardown.
    pub fn reset(&mut self) -> Vec<MacScrollEvent> {
        let mut output = Vec::with_capacity(1);
        match self.state {
            GestureState::Idle => {}
            GestureState::Scrolling => {
                self.push_synthetic(&mut output, Synthetic::GestureEnded);
            }
            GestureState::Momentum => {
                self.push_synthetic(&mut output, Synthetic::MomentumEnd);
            }
        }
        self.accumulator.reset();
        self.last_us = 0;
        self.state = GestureState::Idle;
        output
    }

    pub fn state(&self) -> GestureState {
        self.state
    }

    /// Earliest time at which [`Self::poll`] should close the active phase.
    pub fn next_deadline(&self) -> Option<u64> {
        match self.state {
            GestureState::Idle => None,
            GestureState::Scrolling => Some(self.last_us.saturating_add(GESTURE_IDLE_END_US)),
            GestureState::Momentum => Some(self.last_us.saturating_add(MOMENTUM_IDLE_END_US)),
        }
    }

    pub fn stats(&self) -> ScrollStats {
        self.stats
    }

    fn push_real(&mut self, output: &mut Vec<MacScrollEvent>, msg: &InputMsg, continuous: bool) {
        // Classification has already rejected non-scroll and non-finite input,
        // so this conversion cannot fail. Keep the state machine panic-free
        // anyway: a rejected conversion simply leaves no real event to emit.
        if let Some(scroll) = self.accumulator.convert(msg) {
            output.push(MacScrollEvent {
                scroll,
                continuous,
                synthetic: false,
            });
        }
    }

    fn push_synthetic(&mut self, output: &mut Vec<MacScrollEvent>, synthetic: Synthetic) {
        let (scroll_phase, momentum_phase) = match synthetic {
            Synthetic::GestureBegan => (CG_SCROLL_PHASE_BEGAN, 0),
            Synthetic::GestureEnded => (CG_SCROLL_PHASE_ENDED, 0),
            Synthetic::MomentumBegin => (0, CG_MOMENTUM_PHASE_BEGIN),
            Synthetic::MomentumEnd => (0, CG_MOMENTUM_PHASE_END),
        };
        if synthetic == Synthetic::GestureBegan {
            self.accumulator.reset();
        }
        self.stats.synthesized += 1;
        output.push(MacScrollEvent {
            scroll: MacScroll {
                units_pixel: true,
                dy: 0,
                dx: 0,
                scroll_phase,
                momentum_phase,
            },
            continuous: true,
            synthetic: true,
        });
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScrollInput {
    Wheel,
    Gesture(GestureInput),
    Momentum(MomentumInput),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GestureInput {
    Began,
    Changed,
    Ended,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MomentumInput {
    Began,
    Changed,
    Ended,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Synthetic {
    GestureBegan,
    GestureEnded,
    MomentumBegin,
    MomentumEnd,
}

fn classify_scroll(msg: &InputMsg) -> Option<ScrollInput> {
    let InputMsg::Scroll {
        dx,
        dy,
        phase,
        momentum,
        ..
    } = *msg
    else {
        return None;
    };
    if !dx.is_finite() || !dy.is_finite() {
        return None;
    }
    match (phase, momentum) {
        (ScrollPhase::None, ScrollPhase::None) => Some(ScrollInput::Wheel),
        (phase, ScrollPhase::None) => gesture_input(phase).map(ScrollInput::Gesture),
        (ScrollPhase::None, momentum) => momentum_input(momentum).map(ScrollInput::Momentum),
        _ => None,
    }
}

fn gesture_input(phase: ScrollPhase) -> Option<GestureInput> {
    match phase {
        ScrollPhase::None => None,
        ScrollPhase::Began => Some(GestureInput::Began),
        ScrollPhase::Changed => Some(GestureInput::Changed),
        ScrollPhase::Ended => Some(GestureInput::Ended),
    }
}

fn momentum_input(phase: ScrollPhase) -> Option<MomentumInput> {
    match phase {
        ScrollPhase::None => None,
        ScrollPhase::Began => Some(MomentumInput::Began),
        ScrollPhase::Changed => Some(MomentumInput::Changed),
        ScrollPhase::Ended => Some(MomentumInput::Ended),
    }
}
